$pdo->exec("CREATE TABLE IF NOT EXISTS accounting_service_invoices(id CHAR(32) PRIMARY KEY,owner_id CHAR(32) NOT NULL,client_id CHAR(32) NOT NULL,invoice_no VARCHAR(64) NOT NULL,issued_on DATE NOT NULL,due_on DATE NOT NULL,period_key VARCHAR(20) NOT NULL,items JSON NOT NULL,total DECIMAL(14,2) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'draft',created_by CHAR(32) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_acc_invoice(owner_id,invoice_no),KEY idx_acc_invoice_client(owner_id,client_id,period_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$pdo->exec("CREATE TABLE IF NOT EXISTS accounting_service_payments(id CHAR(32) PRIMARY KEY,owner_id CHAR(32) NOT NULL,invoice_id CHAR(32) NOT NULL,amount DECIMAL(14,2) NOT NULL,paid_on DATE NOT NULL,bank_transaction_id CHAR(32) NULL,created_by CHAR(32) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_acc_payment_invoice(invoice_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$pdo->exec("CREATE TABLE IF NOT EXISTS accounting_period_closures(id CHAR(32) PRIMARY KEY,owner_id CHAR(32) NOT NULL,client_id CHAR(32) NOT NULL,period_key VARCHAR(20) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'open',checklist JSON NOT NULL,comment TEXT NULL,closed_by CHAR(32) NULL,closed_at DATETIME NULL,updated_by CHAR(32) NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_acc_close(owner_id,client_id,period_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
