function accLedgerClient(PDO $pdo,array $ctx,string $owner,string $uid,string $client,bool $manager): void {$members=array_values(array_unique(array_map('strval',$ctx['member_ids']??[$owner])));$marks=implode(',',array_fill(0,count($members),'?'));$sql="SELECT id FROM clients WHERE id=? AND module='accounting' AND created_by IN ({$marks})";if(!$manager)$sql.=' AND (created_by=? OR EXISTS(SELECT 1 FROM client_members cm WHERE cm.client_id=clients.id AND cm.user_id=?))';$q=$pdo->prepare($sql);$q->execute(array_merge([$client],$members,$manager?[]:[$uid,$uid]));if(!$q->fetchColumn())jsonResponse(false,'Клієнта не знайдено.',[],404);requireClaim(resourceClaims($pdo,$uid,'client',$client),'read');}
function accLedgerValidDate(string $value): bool {$date=DateTimeImmutable::createFromFormat('!Y-m-d',$value);return $date instanceof DateTimeImmutable&&$date->format('Y-m-d')===$value;}
function accLedgerValidPeriod(string $value): bool {return preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$value)===1;}
function accLedgerInvoiceEmail(PDO $pdo,string $recipientId,string $clientName,string $invoiceNo,string $dueOn,float $total,string $clientId): void {
    $portalUrl=appUrl('/accounting/portal').'?client='.rawurlencode($clientId);
    $safeClient=htmlspecialchars($clientName,ENT_QUOTES,'UTF-8');$safeInvoice=htmlspecialchars($invoiceNo,ENT_QUOTES,'UTF-8');$safeDue=htmlspecialchars($dueOn,ENT_QUOTES,'UTF-8');$safeUrl=htmlspecialchars($portalUrl,ENT_QUOTES,'UTF-8');$sum=number_format($total,2,',',' ');
    $plain="Для компанії {$clientName} виставлено рахунок № {$invoiceNo} на суму {$sum} грн. Сплатити до {$dueOn}.\n\nПерейдіть до кабінету клієнта: {$portalUrl}";
    $html='<!doctype html><html lang="uk"><body style="margin:0;padding:0;background:#f4faf6;color:#173329;font-family:Arial,Helvetica,sans-serif"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="width:100%;background:#f4faf6"><tr><td align="center" style="padding:32px 16px"><table role="presentation" width="560" cellspacing="0" cellpadding="0" border="0" style="width:100%;max-width:560px;background:#fff;border:1px solid #dcece3;border-radius:18px;overflow:hidden"><tr><td style="height:5px;background:#168b64"></td></tr><tr><td style="padding:32px"><div style="color:#168b64;font-size:12px;font-weight:700;letter-spacing:1px">NEXAFLOW · РАХУНОК</div><h1 style="margin:20px 0 10px;color:#142b22;font-size:28px;line-height:1.2">Вам виставлено рахунок</h1><p style="margin:0;color:#597066;font-size:16px;line-height:1.6">Новий рахунок для компанії <strong>'.$safeClient.'</strong> доступний у вашому кабінеті.</p><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="width:100%;margin:24px 0;border:1px solid #d8eee1;background:#f3fbf6;border-radius:14px"><tr><td style="padding:18px 20px"><div style="color:#7a9187;font-size:11px;font-weight:700;letter-spacing:.7px;text-transform:uppercase">Рахунок №</div><div style="padding-top:6px;color:#16352a;font-size:19px;font-weight:700">'.$safeInvoice.'</div><div style="padding-top:16px;color:#315f4c;font-size:14px;line-height:1.65"><strong>Сума:</strong> '.$sum.' грн<br><strong>Сплатити до:</strong> '.$safeDue.'</div></td></tr></table><a href="'.$safeUrl.'" style="display:inline-block;padding:14px 21px;border-radius:10px;background:#168b64;color:#fff;font-size:15px;font-weight:700;text-decoration:none">Відкрити кабінет клієнта&nbsp;&nbsp;→</a><p style="margin:20px 0 0;color:#74897f;font-size:12px;line-height:1.5">У кабінеті можна переглянути деталі рахунка та повідомити бухгалтера про оплату.</p></td></tr></table></td></tr></table></body></html>';
    sendUserNotificationEmail($pdo,$recipientId,'','Вам виставлено рахунок — NexaFlow',$plain,$html);
}
